SELECT a.status AS status, COUNT(1) AS cnt
FROM t_appointment a
WHERE a.is_delete = 0
AND a.clinic_id = #{clinicId}
AND a.start_time >= #{beginTime}
AND a.start_time <= #{endTime}
AND a.doctor_id = #{doctorId}
GROUP BY a.status

SELECT COUNT(1)
FROM t_appointment
WHERE is_delete = 0
  AND clinic_id = #{clinicId}
  AND doctor_id = #{doctorId}
  AND status NOT IN (6, 7, 8)
  AND start_time < #{endTime}
  AND end_time > #{startTime}
AND id != #{excludeId}

SELECT a.*, cl.clinic_name AS clinic_name, p.name AS patient_name, p.medical_record_no, p.mobile, p.gender, p.age, d.name AS doctor_name, n.name AS nurse_name, c.name AS consultant_name FROM t_appointment a LEFT JOIN t_clinic cl ON a.clinic_id = cl.id LEFT JOIN t_patient p ON a.patient_id = p.id LEFT JOIN t_employee d ON a.doctor_id = d.id LEFT JOIN t_employee n ON a.nurse_id = n.id LEFT JOIN t_employee c ON a.consultant_id = c.id WHERE a.is_delete = 1 AND a.clinic_id = #{clinicId}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.mobile LIKE CONCAT('%', #{keyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{keyword}, '%'))
AND a.doctor_id = #{doctorId} AND a.consultant_id = #{consultantId} AND a.start_time >= #{beginTime} AND a.start_time <= #{endTime} ORDER BY a.update_time DESC

SELECT a.id
FROM t_appointment a
WHERE a.is_delete = 1
AND a.clinic_id = #{clinicId}
AND a.start_time >= #{beginTime}
AND a.start_time <= #{endTime}
